using System.IO;
using UnityEngine;
using UnityEditor;
namespace ZeroToMillionaire.Editor {public static class RigProbe {public static void Fix(){foreach(string path in AssetDatabase.GetAllAssetPaths())if(path.StartsWith("Assets/Resources/Art/animation/")&&path.Contains("-rig-")&&path.EndsWith(".png")){var importer=(TextureImporter)AssetImporter.GetAtPath(path);importer.textureShape=TextureImporterShape.Texture2D;importer.SaveAndReimport();}} public static string Run(){string a="Assets/Resources/Art/animation/front-rig-torso.png";return "data="+Application.dataPath+" exists="+File.Exists(a)+" guid="+AssetDatabase.AssetPathToGUID(a)+" old="+(Resources.Load<Texture2D>("Art/animation/front-idle")!=null)+" direct="+(AssetDatabase.LoadAssetAtPath<Texture2D>(a)!=null)+" type="+(AssetDatabase.LoadMainAssetAtPath(a)?.GetType().FullName??"NULL")+" shape="+((TextureImporter)AssetImporter.GetAtPath(a)).textureShape+" new="+(Resources.Load<Texture2D>("Art/animation/front-rig-torso")!=null);}}}
